/*
 * OS_$INSTALL_DISPLAY_ASTE - Make the display memory a canned object
 *
 * Original address: 0x00E6D29A (SAU2 map: OS_$INSTALL_DISPLAY_ASTE, in the
 * "I E6D1CC OS size = 52C" segment)
 * Size: 460 bytes (0x00E6D29A .. 0x00E6D465); its crash status follows at
 * 0x00E6D468.
 * Generated by: Claude Opus 5.5
 *
 * OS_$INIT calls it for DISPLAY1_$UID with the display's 128 KB at
 * 0x00FC0000 (os/init.c).  It builds the object's VTOCE and location record
 * by hand, activates the AOTE, associates each page of each segment with the
 * physical page behind the display's virtual address, and optionally maps
 * the object at that address and touches every page.
 *
 * Frame (link.w A6,-0xd8; D2-D7/A2-A4 saved; no A5):
 *   (0x08,A6) uid (A2)   (0x0C,A6) va (by ref)   (0x10,A6) size (A3, by ref)
 *   (0x14,A6) touch (by ref, a Domain boolean byte)
 *   (-0xC4) va copy, (-0xB4) map descriptor, (-0xB0) the 0x90-byte VTOCE,
 *   (-0x20) the 0x20-byte location record, (-0xBC) status,
 *   (-0xD0) segment number out, (-0xD6) page count, (-0xD8) segs - 1.
 *
 * Blocks:
 *   0x00E6D2AA-0x00E6D2BC  ppn = VTOP_OR_CRASH(&va copy)
 *   0x00E6D2BE-0x00E6D31E  zero the VTOCE (36 longs) and location record
 *                          (8 longs); VTOCE uid, ACL_$FNDWRX, length;
 *                          location uid and NODE_$ME; descriptor 0;
 *                          AST_$ACTIVATE_AOTE_CANNED
 *   0x00E6D320-0x00E6D352  segments = size rounded up to 32 KB, pages =
 *                          size rounded up to 1 KB (signed divisions)
 *   0x00E6D354-0x00E6D3A6  per segment: AST_$ACTIVATE_ASTE_CANNED, then per
 *                          page (32, until the pages run out)
 *                          AST_$PMAP_ASSOC with consecutive ppns; any
 *                          failure crashes
 *   0x00E6D3AA-0x00E6D412  touch true: the va must lie below segment 0x3A
 *                          (else crash "reference to illegal address");
 *                          MST_$MAP_CANNED_AT(va, uid, 0, size, 0x160001,
 *                          false, false, 0)
 *   0x00E6D414-0x00E6D458  MST_$TOUCH every page (not wired), 1 KB apart
 *
 * Quirks reproduced:
 *   - When the page count runs out the inner loop ends but the segment loop
 *     still counts down (`beq` to the outer `dbf`, 0x00E6D39C and
 *     0x00E6D452); with ceil()-rounded counts the pages always run out in
 *     the last segment.  Both counts are words: a size of 0 gives
 *     segments - 1 = -1 and the `dbf` loops run 65536 times.
 *   - The flags1 argument of AST_$PMAP_ASSOC is `st -(SP)' (true, never
 *     read), allow_no_disk is 0 (0x00E6D372-0x00E6D374).
 *   - The segment number MST_$VA_TO_SEGNO returns through (-0xD0) is
 *     never read.
 */

#include "os/os_internal.h"
#include "node/node.h"

/*
 * `pea (0x94,PC)` at 0x00E6D3D2 = 0x00E6D468, bytes 00 04 00 04.
 */
static const status_$t os_$install_display_crash =
    status_$reference_to_illegal_address;

/* Rounding (`addi.l #0x7fff` / `asr.l #8; asr.l #7`, `addi.l #0x3ff` /
 * `asr.l #8; asr.l #2`) */
#define OS_DISPLAY_SEG_BYTES    0x8000
#define OS_DISPLAY_PAGE_BYTES   0x400
#define OS_DISPLAY_PAGES_PER_SEG_M1 0x1F    /* moveq #0x1f / dbf */

/* MST_$VA_TO_SEGNO's default and bound (`move.w #0x3a`, `cmpi.w #0x39`) */
#define OS_DISPLAY_SEGNO_DEFAULT 0x3A
#define OS_DISPLAY_SEGNO_MAX     0x39

/* MST_$MAP_CANNED_AT flags (`move.l #0x160001,-(SP)` 0x00E6D3E8) */
#define OS_DISPLAY_MAP_FLAGS    0x00160001u

void OS_$INSTALL_DISPLAY_ASTE(uid_t *uid, const uint32_t *va,
                              const int32_t *size, const int8_t *touch)
{
    uint32_t va_copy;                   /* (-0xC4,A6) */
    uint32_t desc;                      /* (-0xB4,A6) */
    os_$init_vtoce_t vtoce;             /* (-0xB0,A6) */
    vtoc_$lookup_req_t loc;             /* (-0x20,A6) */
    status_$t status;                   /* (-0xBC,A6) */
    uint16_t segno;                     /* (-0xD0,A6) */
    uint16_t pages;                     /* (-0xD6,A6) */
    uint16_t segs_m1;                   /* (-0xD8,A6) */
    uint32_t ppn;                       /* D5 */
    aste_t *aste;                       /* A4 */
    uint16_t seg_ctr;                   /* D7w */
    uint16_t seg;                       /* D6w */
    uint16_t page_ctr;                  /* D4w / D3w */
    uint16_t page;                      /* D2w */
    uint16_t left;                      /* D3w / D2w */
    int16_t i;

    /* 0x00E6D2AA-0x00E6D2BC */
    va_copy = *va;
    ppn = VTOP_OR_CRASH(&va_copy);

    /* 0x00E6D2BE-0x00E6D2DA: moveq #0x23 and #0x7 / dbf */
    for (i = 0x23; i >= 0; i--) {
        ((uint32_t *)(void *)&vtoce)[0x23 - i] = 0;
    }
    for (i = 7; i >= 0; i--) {
        ((uint32_t *)(void *)&loc)[7 - i] = 0;
    }

    /* 0x00E6D2DE-0x00E6D31E */
    vtoce.file_uid = *uid;
    vtoce.acl_uid = ACL_$FNDWRX;
    vtoce.length = (uint32_t)*size;
    loc.uid = *uid;
    loc.node = NODE_$ME;
    desc = 0;
    AST_$ACTIVATE_AOTE_CANNED((uint32_t *)(void *)&vtoce,
                              (uint32_t *)(void *)&loc);

    /* 0x00E6D320-0x00E6D352 */
    left = (uint16_t)((*size + (OS_DISPLAY_PAGE_BYTES - 1)) /
                      OS_DISPLAY_PAGE_BYTES);
    pages = left;
    segs_m1 = (uint16_t)((*size + (OS_DISPLAY_SEG_BYTES - 1)) /
                         OS_DISPLAY_SEG_BYTES - 1);
    seg_ctr = segs_m1;

    /* 0x00E6D354-0x00E6D3A6 */
    seg = 0;
    do {
        aste = AST_$ACTIVATE_ASTE_CANNED(uid, seg);
        page_ctr = OS_DISPLAY_PAGES_PER_SEG_M1;
        page = 0;
        for (;;) {
            AST_$PMAP_ASSOC(aste, page, ppn, 0x00FF, 0, &status);
            if (status != status_$ok) {
                CRASH_SYSTEM(&status);
            }
            ppn++;
            if (--left == 0) {
                break;
            }
            page++;
            if (page_ctr-- == 0) {
                break;
            }
        }
        seg++;
    } while (seg_ctr-- != 0);

    /* 0x00E6D3AA-0x00E6D412 */
    if (*touch < 0) {
        if (MST_$VA_TO_SEGNO(va_copy, &segno, OS_DISPLAY_SEGNO_DEFAULT) >
            OS_DISPLAY_SEGNO_MAX) {
            CRASH_SYSTEM(&os_$install_display_crash);
        }
        MST_$MAP_CANNED_AT(va_copy, uid, 0, (uint32_t)*size,
                           OS_DISPLAY_MAP_FLAGS, 0, 0, desc, &status);
        if (status != status_$ok) {
            CRASH_SYSTEM(&status);
        }

        /* 0x00E6D414-0x00E6D458 */
        left = pages;
        seg_ctr = segs_m1;
        do {
            page_ctr = OS_DISPLAY_PAGES_PER_SEG_M1;
            for (;;) {
                MST_$TOUCH(va_copy, &status, 0);
                if (status != status_$ok) {
                    CRASH_SYSTEM(&status);
                }
                va_copy += OS_DISPLAY_PAGE_BYTES;
                if (--left == 0) {
                    break;
                }
                if (page_ctr-- == 0) {
                    break;
                }
            }
        } while (seg_ctr-- != 0);
    }
}
